//! Spike r0-12: the CLI skeleton for the size and start baseline.
//!
//! The command tree is the Go spinup tree (`commands.rs`, generated by
//! `tools/gen_commands.py`). Most commands are stubs. A few commands do
//! real work, so the linker keeps the crates that the R1 CLI needs: clap
//! and clap_complete, minijinja, toml and toml_edit, the R0.4 HTTP client
//! (ureq, rustls, ring), zstd and tar, sha2 and ed25519-dalek, inquire,
//! regex, semver, walkdir, and dirs.

mod commands;

use std::io::{IsTerminal, Read};
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::sync::Arc;

use anyhow::{Context, bail};
use clap::{CommandFactory, Parser};
use commands::Cli;
use sha2::{Digest, Sha256};

/// One embedded template archive (tar + zstd).
pub struct Archive {
    pub version: &'static str,
    pub sha256: &'static str,
    pub tar_bytes: usize,
    pub data: &'static [u8],
}

include!(concat!(env!("OUT_DIR"), "/archives.rs"));

fn main() -> ExitCode {
    let cli = Cli::parse();
    match run(&cli) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("spinup: {err:#}");
            ExitCode::FAILURE
        }
    }
}

fn run(cli: &Cli) -> anyhow::Result<()> {
    let path = cli.path();
    let args = cli.args();
    match path {
        "" => {
            Cli::command().print_help()?;
            Ok(())
        }
        "version" => {
            println!(
                "spinup {} ({} commands)",
                env!("CARGO_PKG_VERSION"),
                commands::LEAVES
            );
            for a in &ARCHIVES {
                println!("templates {}", a.version);
            }
            Ok(())
        }
        "cache list" => cache_list(cli.json),
        "new" => new_app(cli, args),
        "self-update" => self_update(args),
        "plugin verify" => plugin_verify(args),
        "doctor" => doctor(cli),
        p if p.starts_with("completion ") => {
            let shell: clap_complete::Shell = p["completion ".len()..]
                .parse()
                .map_err(|e| anyhow::anyhow!("{e}"))?;
            clap_complete::generate(shell, &mut Cli::command(), "spinup", &mut std::io::stdout());
            Ok(())
        }
        p => {
            println!("spinup {p}: stub (R0.12 skeleton)");
            Ok(())
        }
    }
}

/// Decodes one archive: the sha256 check, then zstd and tar. Returns the
/// files (path, bytes).
pub fn decode(a: &Archive) -> anyhow::Result<Vec<(String, Vec<u8>)>> {
    let sum: String = Sha256::digest(a.data)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    if sum != a.sha256 {
        bail!(
            "templates {} has the wrong checksum\nTry: reinstall spinup",
            a.version
        );
    }
    let raw = zstd::stream::decode_all(a.data).context("decode the zstd stream")?;
    let mut files = Vec::new();
    let mut tar = tar::Archive::new(raw.as_slice());
    for entry in tar.entries()? {
        let mut entry = entry?;
        let name = entry.path()?.to_string_lossy().into_owned();
        let mut data = Vec::new();
        entry.read_to_end(&mut data)?;
        files.push((name, data));
    }
    Ok(files)
}

fn cache_list(json: bool) -> anyhow::Result<()> {
    let mut rows = Vec::new();
    for a in &ARCHIVES {
        let files = decode(a)?;
        let packs: std::collections::BTreeSet<&str> = files
            .iter()
            .filter_map(|(n, _)| n.strip_prefix("packs/")?.split('/').next())
            .collect();
        rows.push(serde_json::json!({
            "version": a.version,
            "files": files.len(),
            "packs": packs.len(),
            "compressed": a.data.len(),
            "expanded": a.tar_bytes,
        }));
    }
    if json {
        println!("{}", serde_json::to_string_pretty(&rows)?);
        return Ok(());
    }
    let mut env = minijinja::Environment::new();
    env.add_template(
        "list",
        "{% for r in rows %}{{ r.version }}  {{ r.packs }} packs  {{ r.files }} files  {{ r.compressed }} bytes\n{% endfor %}",
    )?;
    print!(
        "{}",
        env.get_template("list")?.render(
            minijinja::context! { rows => minijinja::Value::from(minijinja::value::Serde(&rows)) }
        )?
    );
    Ok(())
}

fn new_app(cli: &Cli, args: &[String]) -> anyhow::Result<()> {
    let name = match args.first() {
        Some(n) => n.clone(),
        None if !cli.non_interactive && std::io::stdin().is_terminal() => {
            inquire::Text::new("App name:").prompt()?
        }
        None => bail!(
            "spinup new needs an app name, and there is no terminal for a prompt\nTry: spinup new <name>"
        ),
    };
    if !regex::Regex::new("^[a-z][a-z0-9-]*$")?.is_match(&name) {
        bail!(
            "the app name {name:?} is not valid: use lower-case letters, digits, and dashes\nTry: spinup new my-app"
        );
    }
    let latest = ARCHIVES.last().expect("three archives");
    let files = decode(latest)?;
    let root = PathBuf::from(cli.dir.as_deref().unwrap_or(".")).join(&name);
    let pack: toml::Table = files
        .iter()
        .find(|(n, _)| n == "packs/base/pack.toml")
        .map(|(_, d)| toml::from_str(std::str::from_utf8(d).unwrap_or("")))
        .transpose()?
        .unwrap_or_default();
    let mut written = 0;
    for (n, data) in &files {
        let Some(rel) = n.strip_prefix("packs/base/files/") else {
            continue;
        };
        let rel = rel.strip_suffix(".tmpl").unwrap_or(rel);
        let dest = root.join(rel);
        if !cli.dry_run {
            std::fs::create_dir_all(dest.parent().unwrap_or(Path::new(".")))?;
            std::fs::write(&dest, data)?;
        }
        written += 1;
    }
    let mut doc = toml_edit::DocumentMut::new();
    doc["app"] = toml_edit::value(name.as_str());
    doc["templates"] = toml_edit::value(latest.version);
    doc["packs"] = toml_edit::value(toml_edit::Array::from_iter([pack
        .get("name")
        .and_then(|v| v.as_str())
        .unwrap_or("base")]));
    if !cli.dry_run {
        std::fs::create_dir_all(&root)?;
        std::fs::write(root.join("spinup.lock.toml"), doc.to_string())?;
    }
    println!("created {} ({written} files)", root.display());
    Ok(())
}

/// The R0.4 client: ureq with rustls and the ring provider.
fn client() -> ureq::Agent {
    ureq::Agent::config_builder()
        .tls_config(
            ureq::tls::TlsConfig::builder()
                .unversioned_rustls_crypto_provider(Arc::new(
                    rustls::crypto::ring::default_provider(),
                ))
                .build(),
        )
        .build()
        .into()
}

fn self_update(args: &[String]) -> anyhow::Result<()> {
    let agent = client();
    let current = semver::Version::parse(env!("CARGO_PKG_VERSION"))?;
    let Some(url) = args.first() else {
        println!("spinup {current}: no release URL given (the skeleton does not look up releases)");
        return Ok(());
    };
    let body: serde_json::Value = agent.get(url).call()?.body_mut().read_json()?;
    let latest = semver::Version::parse(body["version"].as_str().unwrap_or("0.0.0"))?;
    println!("current {current}, latest {latest}");
    Ok(())
}

fn unhex(s: &str) -> anyhow::Result<Vec<u8>> {
    if !s.len().is_multiple_of(2) {
        bail!("odd hex length\nTry: pass the full hex string");
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(Into::into))
        .collect()
}

fn plugin_verify(args: &[String]) -> anyhow::Result<()> {
    let [key, sig, file] = args else {
        bail!(
            "plugin verify needs <public key hex> <signature hex> <file>\nTry: spinup plugin verify KEY SIG FILE"
        );
    };
    let key: [u8; 32] = unhex(key)?
        .try_into()
        .map_err(|_| anyhow::anyhow!("the key is not 32 bytes\nTry: pass an ed25519 public key"))?;
    let sig: [u8; 64] = unhex(sig)?.try_into().map_err(|_| {
        anyhow::anyhow!("the signature is not 64 bytes\nTry: pass an ed25519 signature")
    })?;
    let key = ed25519_dalek::VerifyingKey::from_bytes(&key)?;
    let data = std::fs::read(file)?;
    key.verify_strict(&data, &ed25519_dalek::Signature::from_bytes(&sig))
        .map_err(|e| {
            anyhow::anyhow!(
                "the signature of {file} is not valid: {e}\nTry: download the file again"
            )
        })?;
    println!("{file}: signature ok");
    Ok(())
}

fn doctor(cli: &Cli) -> anyhow::Result<()> {
    let dir = cli.dir.as_deref().unwrap_or(".");
    let n = walkdir::WalkDir::new(dir)
        .max_depth(3)
        .into_iter()
        .filter_map(Result::ok)
        .count();
    println!("project {dir}: {n} entries");
    if let Some(cache) = dirs::cache_dir() {
        println!("cache {}", cache.join("spinup").display());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_command_tree_is_valid() {
        Cli::command().debug_assert();
        const { assert!(commands::LEAVES >= 60) };
    }

    #[test]
    fn archives_differ_and_decode() {
        assert_ne!(ARCHIVES[0].sha256, ARCHIVES[1].sha256);
        assert_ne!(ARCHIVES[1].sha256, ARCHIVES[2].sha256);
        for a in &ARCHIVES {
            let files = decode(a).unwrap();
            assert_eq!(files[0].0, "VERSION");
            assert_eq!(files[0].1, format!("{}\n", a.version).into_bytes());
        }
    }

    #[test]
    fn plugin_verify_checks_an_ed25519_signature() {
        // RFC 8032 test 1: the empty message.
        let key = "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a";
        let sig = "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b";
        let file = std::env::temp_dir().join(format!("r0-12-empty-{}", std::process::id()));
        std::fs::write(&file, b"").unwrap();
        let f = file.to_string_lossy().into_owned();
        plugin_verify(&[key.into(), sig.into(), f.clone()]).unwrap();
        let mut bad = sig.to_owned();
        bad.replace_range(0..2, "e6");
        assert!(plugin_verify(&[key.into(), bad, f]).is_err());
        std::fs::remove_file(file).unwrap();
    }
}
